"""Memory retrieval: the training examples closest to the current question."""

import json
import math
from collections import Counter
from pathlib import Path

from langchain_core.tools import tool

# One tool result is offloaded to a file by the agent framework above 80000
# characters, so the delivered memory stays below that ceiling.
MAX_CHARS = 60000
NGRAM = 3
# An n-gram carried by at least half of the examples separates nothing, so it is
# dropped from both sides before ranking. Every example shares the task's prompt
# template with every question, so the template is what this removes, leaving
# the text that is specific to one problem.
SHARED_DF = 0.5


def example_text(example: dict) -> str:
    """What the example shows the solver: the problem without the prompt template."""
    return str(example.get("raw_question") or example["input"])


def ngrams(text: str) -> list[str]:
    """Character n-grams, which match across word forms, Chinese text and identifiers."""
    text = " ".join(str(text).split()).lower()
    return [text[index:index + NGRAM] for index in range(max(0, len(text) - NGRAM + 1))]


class Ranker:
    """Cosine similarity between IDF-weighted character n-gram vectors.

    Both the incoming question and the stored examples are wrapped in the same
    prompt template, so ranking the question's whole text against examples
    rendered from the problem alone scores the template's phrases as if they
    described the example. Indexing the examples by their `input` puts the same
    template on both sides, and dropping the n-grams that most examples carry
    takes it back out again.
    """

    def __init__(self, examples: list[dict]):
        self.vectors = [Counter(ngrams(example["input"])) for example in examples]
        frequency = Counter()
        for vector in self.vectors:
            frequency.update(vector.keys())
        total = len(examples) or 1
        self.shared = {gram for gram, count in frequency.items() if count >= SHARED_DF * total}
        self.idf = {
            gram: math.log((total + 1) / (count + 1)) + 1.0 for gram, count in frequency.items()
        }
        self.norms = [
            math.sqrt(
                sum((self.idf[gram] * count) ** 2 for gram, count in vector.items()
                    if gram not in self.shared)
            ) or 1.0
            for vector in self.vectors
        ]

    def rank(self, query: str) -> list[int]:
        """Example indices, closest to the query first."""
        grams = {
            gram: count for gram, count in Counter(ngrams(query)).items()
            if gram not in self.shared
        }
        norm = math.sqrt(
            sum((self.idf.get(gram, 0.0) * count) ** 2 for gram, count in grams.items())
        ) or 1.0
        scored = [
            (
                sum(
                    self.idf[gram] ** 2 * count * grams[gram]
                    for gram, count in vector.items() if gram in grams
                ) / (norm * self.norms[index]),
                index,
            )
            for index, vector in enumerate(self.vectors)
        ]
        scored.sort(key=lambda pair: (-pair[0], pair[1]))
        return [index for _, index in scored]


def make_tool(input_text: str):
    examples = json.loads(Path("/harness/memory/memory.json").read_text())["examples"]
    closest = Ranker(examples).rank(input_text)

    @tool
    def retrieve_examples() -> str:
        """Get the training Q/A examples for the current problem, closest example first."""
        parts = []
        total_chars = 0
        for index in closest:
            example = examples[index]
            part = f"Q: {example_text(example)}\nA: {example['target']}"
            if total_chars + len(part) > MAX_CHARS:
                continue
            parts.append(part)
            total_chars += len(part) + 2
        return "\n\n".join(parts)

    return retrieve_examples

"""Offline FewShotAll learning, run separately from the solver."""

import argparse
import json
from pathlib import Path


def prepare_memory(train: list[dict], epochs: int) -> dict:
    examples = []
    for _ in range(epochs):
        for item in train:
            example = {"input": item["input"], "target": item["target"]}
            if "raw_question" in item:
                example["raw_question"] = item["raw_question"]
            examples.append(example)
    return {"examples": examples}


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--train", default="/input/train.json")
    parser.add_argument("--output", default="/output/memory.json")
    parser.add_argument("--epochs", type=int, default=1)
    args = parser.parse_args()
    train = json.loads(Path(args.train).read_text())
    Path(args.output).write_text(json.dumps(prepare_memory(train, args.epochs), indent=2))

"""Answer parsing copied from the selected baseline."""

import json
import re


def extract_json_field(text: str, field: str, default: str = "") -> str:
    """Helper function to extract a field from JSON in LLM response."""
    # Try direct parse
    try:
        data = json.loads(text)
        if isinstance(data, dict):
            return str(data.get(field, default))
    except json.JSONDecodeError:
        pass

    # Try code blocks: ```json ... ``` or ``` ... ```
    for match in re.finditer(r"```(?:json)?\s*([\s\S]*?)\s*```", text):
        try:
            data = json.loads(match.group(1))
            if isinstance(data, dict):
                return str(data.get(field, default))
        except json.JSONDecodeError:
            pass

    # Find balanced braces and try parsing
    for start in range(len(text)):
        if text[start] != "{":
            continue
        depth, pos, in_str = 1, start + 1, False
        while pos < len(text) and depth > 0:
            c = text[pos]
            if c == '"' and (pos == 0 or text[pos - 1] != "\\"):
                in_str = not in_str
            elif not in_str:
                depth += 1 if c == "{" else (-1 if c == "}" else 0)
            pos += 1
        if depth == 0:
            candidate = text[start:pos]
            candidate = re.sub(
                r",\s*([\]}])", r"\1", candidate
            )  # Remove trailing commas
            try:
                data = json.loads(candidate)
                if isinstance(data, dict):
                    return str(data.get(field, default))
            except json.JSONDecodeError:
                pass

    # Regex fallback
    match = re.findall(rf'"{field}"\s*:\s*"([^"]*)"', text)
    return match[-1] if match else default

"""Evaluators for kept MCE and OOD tasks."""

from __future__ import annotations

import json
import re
from collections.abc import Callable

from .constants import TRANSFER_TASKS


def extract_final_answer(response_text: str) -> str:
    if not response_text:
        return ""

    text = response_text.strip()
    if text.startswith("```"):
        lines = text.splitlines()
        payload = []
        in_json = False
        for line in lines:
            stripped = line.strip()
            if stripped.startswith("```json"):
                in_json = True
                continue
            if stripped.startswith("```") and in_json:
                break
            if in_json:
                payload.append(line)
        if payload:
            text = "\n".join(payload)
        elif "```" in text:
            parts = text.split("```")
            if len(parts) >= 3:
                text = parts[1]
                if text.startswith("json"):
                    text = text[4:].strip()

    try:
        data = json.loads(text)
        if isinstance(data, dict) and "final_answer" in data:
            return str(data["final_answer"])
    except json.JSONDecodeError:
        pass

    match = re.search(r"\{[^{}]*(?:\{[^{}]*\}[^{}]*)*\}", text)
    if match:
        try:
            data = json.loads(match.group())
            if isinstance(data, dict) and "final_answer" in data:
                return str(data["final_answer"])
        except json.JSONDecodeError:
            pass

    return response_text


def eval_finer(prediction: str, target: str) -> bool:
    return extract_final_answer(prediction).lower().strip() == target.lower().strip()


def eval_uspto(prediction: str, target: str) -> dict:
    def parse_reactants(smiles: str) -> set[str]:
        return {
            part.strip().lower() for part in smiles.strip().split(".") if part.strip()
        }

    pred_set = parse_reactants(extract_final_answer(prediction))
    target_set = parse_reactants(target)
    if not pred_set and not target_set:
        jaccard = 1.0
    elif not pred_set or not target_set:
        jaccard = 0.0
    else:
        jaccard = len(pred_set & target_set) / len(pred_set | target_set)
    return {"correct": pred_set == target_set, "jaccard_similarity": jaccard}


def eval_symptom2disease(prediction: str, target: str) -> bool:
    text = extract_final_answer(prediction)
    match = re.search(r"\[DIAGNOSIS\](.*?)\[/DIAGNOSIS\]", text, re.I | re.S)
    if match:
        text = match.group(1).strip()
    else:
        match = re.search(
            r"(?:diagnosis|final diagnosis|conclusion)[:：]\s*([^\n]+)", text, re.I
        )
        if match:
            text = match.group(1).strip()

    def normalize(value: str) -> str:
        value = value.lower().strip()
        value = re.sub(r"\s+", " ", value)
        return re.sub(r"[.!?]+$", "", value)

    return normalize(text) == normalize(target)


def eval_lawbench(prediction: str, target: str) -> dict:
    def parse_charges(text: str) -> set[str]:
        text = extract_final_answer(text).strip()
        match = re.search(r"\[罪名\](.*?)(?:<eoa>|$)", text)
        if match:
            text = match.group(1).strip()
        elif "罪名:" in text:
            text = text.split("罪名:")[-1]
        text = re.sub(r"<eoa>.*", "", text).strip()
        for sep in [";", "；", ",", "，", "、"]:
            if sep in text:
                return {part.strip() for part in text.split(sep) if part.strip()}
        return {text} if text else set()

    pred_charges = parse_charges(prediction)
    true_charges = parse_charges(target)
    tp = len(pred_charges & true_charges)
    fp = len(pred_charges - true_charges)
    fn = len(true_charges - pred_charges)
    precision = tp / (tp + fp) if tp + fp else 0.0
    recall = tp / (tp + fn) if tp + fn else 0.0
    f1 = 2 * precision * recall / (precision + recall) if precision + recall else 0.0
    return {
        "correct": pred_charges == true_charges,
        "f1": f1,
        "precision": precision,
        "recall": recall,
        "tp": tp,
        "fp": fp,
        "fn": fn,
    }


def eval_aegis(prediction: str, target: str) -> bool:
    pred = extract_final_answer(prediction).lower()
    if "unsafe" in pred:
        pred = "unsafe"
    elif "safe" in pred:
        pred = "safe"
    else:
        pred = pred.strip()
    return pred == target.lower().strip()


def eval_classification(prediction: str, target: str) -> bool:
    def normalize(text: str) -> str:
        text = extract_final_answer(text).lower().strip()
        text = text.replace("_", " ")
        text = re.sub(r"\s+", " ", text)
        return re.sub(r"[.!?]+$", "", text)

    return normalize(prediction) == normalize(target)


def get_evaluator(task: str) -> Callable:
    if task == "FiNER":
        return lambda pred, target, **kwargs: eval_finer(pred, target)
    if task == "USPTO":

        def _eval_uspto(pred: str, target: str, **kwargs) -> dict:
            raw = eval_uspto(pred, target)
            return {
                "was_correct": raw["correct"],
                "metrics": {"jaccard_similarity": raw["jaccard_similarity"]},
            }

        return _eval_uspto
    if task == "Symptom2Disease":
        return lambda pred, target, **kwargs: eval_symptom2disease(pred, target)
    if task == "LawBench":

        def _eval_lawbench(pred: str, target: str, **kwargs) -> dict:
            raw = eval_lawbench(pred, target)
            return {
                "was_correct": raw["correct"],
                "metrics": {
                    "f1": raw["f1"],
                    "precision": raw["precision"],
                    "recall": raw["recall"],
                    "tp": raw["tp"],
                    "fp": raw["fp"],
                    "fn": raw["fn"],
                },
            }

        return _eval_lawbench
    if task == "AEGIS":
        return lambda pred, target, **kwargs: eval_aegis(pred, target)
    if task in TRANSFER_TASKS:
        return lambda pred, target, **kwargs: eval_classification(pred, target)
    raise ValueError(f"Unknown task: {task}")

