import json, re, collections, sys
sys.path.insert(0,"/workspace/benchmark")
from data.evaluators import extract_final_answer
def parse_charges(text):
    text = extract_final_answer(text).strip()
    m = re.search(r"\[罪名\](.*?)(?:<eoa>|$)", text)
    if m: text = m.group(1).strip()
    elif "罪名:" in text: text = text.split("罪名:")[-1]
    text = re.sub(r"<eoa>.*", "", text).strip()
    for sep in [";","；",",","，","、"]:
        if sep in text:
            return {p.strip() for p in text.split(sep) if p.strip()}
    return {text} if text else set()

RUN="/workspace/runs/562ab0872291f6e171db9409b3576432d425084c"
mem=json.load(open(f"{RUN}/LawBench/memory.json"))["examples"]
vocab=set()
for e in mem:
    vocab |= parse_charges(e["target"])
print("memory charge vocabulary size:",len(vocab))
rows=[json.loads(l) for l in open(f"{RUN}/results/samples.jsonl")]
law=[r for r in rows if r["task"]=="LawBench" and r["status"]=="ok"]

def ed(a,b):
    prev=list(range(len(b)+1))
    for i,ca in enumerate(a,1):
        cur=[i]
        for j,cb in enumerate(b,1):
            cur.append(min(prev[j]+1,cur[j-1]+1,prev[j-1]+(ca!=cb)))
        prev=cur
    return prev[-1]

def snap(pred_set, maxd=1):
    out=set()
    for p in pred_set:
        best=None;bd=99
        for v in vocab:
            d=ed(p,v)
            if d<bd: bd=d;best=v
        out.add(best if bd<=maxd else p)
    return out

for maxd in [0,1,2]:
    tot=0; fixed=0; broken=0
    for r in law:
        p=parse_charges(r["prediction"]); t=parse_charges(r["target"])
        s=snap(p,maxd)
        if r["was_correct"]: 
            if s!=t: broken+=1
        else:
            if s==t: fixed+=1
        tot+=1
    print(f"snap maxd={maxd}: fixed {fixed}, broken {broken}, accuracy {sum(r['was_correct'] for r in law)+fixed-broken}/{tot} = {(sum(r['was_correct'] for r in law)+fixed-broken)/tot:.3f}")

# how many val target charges are in vocab?
val_t=set()
for r in law: val_t |= parse_charges(r["target"])
inmem=sum(1 for v in val_t if v in vocab)
print(f"val distinct charges {len(val_t)}, present in memory vocab: {inmem}")
# per-sample: is target set fully covered by vocab?
full=0
for r in law:
    if parse_charges(r["target"]) <= vocab: full+=1
print("samples whose target set is fully in memory vocab:",full,"/",len(law))
