import json, collections
NEW="/workspace/runs/57a4d05c3f5fc24a9196220ef26c5254ea360077"
OLD="/workspace/runs/562ab0872291f6e171db9409b3576432d425084c"
def load(run):
    d={}
    for l in open(f"{run}/results/samples.jsonl"):
        r=json.loads(l); d[(r["task"],r["example_index"],r["sample_index"])]=r
    return d
a,b=load(OLD),load(NEW)
for task in ["USPTO","Symptom2Disease","LawBench"]:
    cat=collections.Counter(); details=collections.defaultdict(list)
    for key,r in b.items():
        if key[0]!=task: continue
        o=a[key]
        ok_o = o["status"]=="ok" and o["was_correct"]
        ok_n = r["status"]=="ok" and r["was_correct"]
        if ok_o and ok_n: c="both right"
        elif ok_o and not ok_n: c="LOST"
        elif not ok_o and ok_n: c="GAINED"
        else: c="both wrong"
        cat[c]+=1
        if c=="LOST": details[c].append((key[1],key[2],o["prediction"][:40],r["prediction"][:40],r["status"],r["tool_calls"][:4]))
        if c=="GAINED": details[c].append((key[1],key[2],o["prediction"][:40],r["prediction"][:40],"",""))
    print(f"== {task}: {dict(cat)}")
    for c in ["LOST","GAINED"]:
        for d in details[c][:14]: print(f"    {c} q{d[0]} s{d[1]}: {d[2]!r} -> {d[3]!r} status={d[4]} tools={d[5]}")
EOF

